{
  "name": "@phantomcodes/cli",
  "version": "1.5.1",
  "description": "Connects Claude Code, Codex, pi and other coding agents to Phantom AI, an OpenAI-compatible API, and manages your keys, credit and spending caps from the terminal.",
  "keywords": [
    "phantom",
    "api-key",
    "agent",
    "llm",
    "inference",
    "cli",
    "openai-compatible",
    "pi-package",
    "agent-skill",
    "claude-code",
    "codex",
    "cursor",
    "opencode",
    "ai-agents",
    "solana",
    "usdc",
    "wallet"
  ],
  "homepage": "https://phantom.codes/",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/connortessaro/phantom.git",
    "directory": "cli"
  },
  "type": "module",
  "bin": {
    "phantom": "bin/phantom.mjs"
  },
  "files": [
    "bin",
    "dist",
    "skills",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=24"
  },
  "dependencies": {
    "jsonc-parser": "^3.3.1",
    "smol-toml": "^1.9.0"
  },
  "scripts": {
    "build": "tsc -p .",
    "coverage": "vitest run --coverage",
    "dev": "node src/phantom.mts",
    "prepare": "npm run build",
    "test": "vitest run",
    "typecheck": "tsc -p . --noEmit",
    "version": "node scripts/sync-version.mjs && git add src/core/version.mts"
  },
  "pi": {
    "skills": [
      "./skills"
    ]
  },
  "bugs": {
    "url": "https://github.com/connortessaro/phantom/issues"
  },
  "license": "SEE LICENSE IN LICENSE",
  "author": "Harbor Financial LLC",
  "devDependencies": {
    "@types/node": "^24.19.2",
    "@vitest/coverage-v8": "^5.0.3",
    "typescript": "^6.0.3",
    "vitest": "^5.0.5"
  },
  "publishConfig": {
    "access": "public"
  },
  "exports": {
    ".": {
      "types": "./dist/phantom.d.mts",
      "import": "./dist/phantom.mjs"
    }
  }
}
